var galaxy;
var nebula;
var stars;

var loading = 1;


/*--------------*/


function setup() {
  createCanvas(500, 500);
  background(10, 0, 20);

  galaxy = new Galaxy(width, height);
  nebula = new Nebula(width, height);
  stars = new Star(width, height);
}


/*--------------*/


function draw() {
  if (loading) {
    displayLoading();
    loading = 0;  // toggle loading
  } else {
    noiseSeed(random(9007199254740991));
    createUniverse();
    // noLoop() removed for animation
  }
}

/*--------------*/

function mousePressed() {
  loading = 1;  // toggle loading
  loop();
}


/*--------------*/

// dipslay loading message
function displayLoading() {
	noStroke();

	fill(255, 50);
  rect(0, 0, width, height); // semi transparent light background

	fill(255);
  textSize(28);
  textAlign(CENTER, CENTER);
  text("Loading...", width/2, height/2);
}


/*--------------*/

// create a new random universe
function createUniverse() {
  galaxy.create();  // create galaxy
  nebula.create();  // create nebula

  // create stars
  stars.clear();
  stars.addSimpleStar(300, 1, 70);
  stars.addSimpleStar(300, 1, 130);
  stars.addSimpleStar(300, 1, 170);
  stars.addSimpleStar( 40, 2, 150);
  stars.addSimpleStar( 40, 2,  50);
  stars.addSimpleStar( 70, 3,  100);
  stars.addSimpleStar( 30, 3,  200);
  stars.addBigStar(5);

  displayUniverse();  // display
}


/*--------------*/


function displayUniverse() {
  // display background
  background(10, 0, 20);
  nebula.displayBG();

  // display stars
  stars.display(0, 0);

  // display nebula
  nebula.displayFG();

  // display galaxy
  let theta = random(-1, 1);
  let x = width/2 + random(-100, 100);
  let y = height/2 + random(-100, 100);
  let w = random(width/2., width);
  let h = random(height/3, 3*height/4);
  galaxy.display(theta, x, y, w, h);
}

/*--------------*/

function Galaxy(w, h) {
	this.spiral = createGraphics(w, h);
	this.galaxy = createGraphics(w, h);

	this.config(w, h);
}

/*--------------*/

Galaxy.prototype.config = function(w, h) {
	this.x = w/2;
	this.y = h/2;

	this.phi = radians(2);

	this.maxJ = 200;
	this.maxI = 250;

	this.nJ = 1/50.0;
	this.nI = 1/40.0;

	this.r = 1;
	this.w = 1/20.0

	this.diam = 3;	
}

/*--------------*/

Galaxy.prototype.create = function() {
	this.spiral.clear();
	this.galaxy.clear();

	this.spiral.push();

	this.spiral.noStroke();

	for (let j =0; j < this.maxJ; j++) {
		let fadeJ = quadraticFade(this.maxJ, j);
		for(let i = 0; i < this.maxI; i++) {
			let fadeI = linearFade(this.maxI, i);

			let red = 255;
			let green = 235;
			let blue = 200 + 255/500 *pow(i, 1.1);

			let n = noise(this.nI*i, this.nJ*j);
			let alpha = 255*n*fadeI*fadeJ;

			this.spiral.fill(red, green, blue, alpha);

			let dx = i*this.r*cos(this.w*i + j*this.phi);
			let dy = i*this.r*sin(this.w*i + j*this.phi);

			this.spiral.ellipse(this.x + dx, this.y + dy, this.diam);
		}
	}
	this.spiral.pop();

	this.galaxy.push();
	this.galaxy.imageMode(CENTER);
	this.galaxy.translate(this.x, this.y);

	this.galaxy.image(this.spiral, 0, 0);

	this.galaxy.rotate(PI/3);
	this.galaxy.image(this.spiral, 0, 0);

	this.galaxy.rotate(PI);
	this.galaxy.image(this.spiral, 0, 0);

	this.galaxy.rotate(-PI/3);
	this.galaxy.image(this.spiral, 0, 0);
	this.galaxy.pop();
}

/*--------------*/

Galaxy.prototype.display = function(theta, x, y, w, h) {
	push();
	translate(x, y);
	rotate(theta);
	imageMode(CENTER);
	image(this.galaxy, 0, 0, w, h);
	pop();
}

/*--------------*/

function quadraticFade(x, i) {
	let half_x = x/2;
	return -1/pow(half_x, 2) * i * (i - half_x);
}

/*--------------*/

function linearFade(x, i) {
	return 1/x * (x - i);
}

/*--------------*/

function Nebula(w, h) {
	this.dark = createGraphics(w, h);
	this.dark.pixelDensity(1);
	this.light = createGraphics(w, h);
	this.light.pixelDensity(1);
	this.blue = createGraphics(w, h);
	this.blue.pixelDensity(1);

	this.w = w;
	this.h = h;

	this.config();
}

/*--------------*/

Nebula.prototype.config = function() {
	this.slopeA = 1.5;
	this.slopeB = 4.5;

	this.disp = [];
	for (let i = 0; i < 6; i++) this.disp.push(random(-500, 500));

	this.mult = [1/600., 1/100., 1/800.];

	this.darker_color = [15, 0, 25];
	this.lighter_color = [135, 70,115];
	this.background_color = [8, 0, 40];
}

/*--------------*/

Nebula.prototype.create = function() {
	noiseDetail(6, 0.5);

	this.dark.loadPixels();
	this.light.loadPixels();
	this.blue.loadPixels();

	for (let i = 0; i < this.w; i += 1) {
		for (let j = 0; j < this.h; j += 1) {

			let n1 = noise(this.disp[0] + this.mult[0]*i, this.disp[1]  + this.mult[0]*j);
			let z1 = map(n1, 0, 1, -8, 8);
			let l1a = 1 / (1 + this.slopeA*exp(z1));
			let l1b = 1 / (1 + this.slopeB*exp(-z1));

			let n2 = noise(this.disp[2] + this.mult[1]*i, this.disp[3] + this.mult[1]*j);
			let z2 = map(n2, 0, 1, -8, 8);
			let l2a = 1 / (1 +  this.slopeA*exp(z2));
			let l2b = 1 / (1 +  this.slopeB*exp(-z2));

			noiseDetail(6, 0.45);
			let n3 = noise(this.disp[4] + this.mult[2]*i, this.disp[5]  + this.mult[2]*j);
			let z3 = map(n1, 0, 1, -8, 8);
			let l3 = 1 / (1 + exp(-z3));

			this.dark.pixels[4*(i + j*this.w) + 0] = this.darker_color[0];
			this.dark.pixels[4*(i + j*this.w) + 1] = this.darker_color[1];
			this.dark.pixels[4*(i + j*this.w) + 2] = this.darker_color[2];
			this.dark.pixels[4*(i + j*this.w) + 3] = 255 *l1a*l2a;

			this.light.pixels[4*(i + j*this.w) + 0] = this.lighter_color[0];
			this.light.pixels[4*(i + j*this.w) + 1] = this.lighter_color[1];
			this.light.pixels[4*(i + j*this.w) + 2] = this.lighter_color[2];
			this.light.pixels[4*(i + j*this.w) + 3] = 255*l1b*l2b;

			this.blue.pixels[4*(i + j*this.w) + 0] = this.background_color[0];
			this.blue.pixels[4*(i + j*this.w) + 1] = this.background_color[1];
			this.blue.pixels[4*(i + j*this.w) + 2] = this.background_color[2];
			this.blue.pixels[4*(i + j*this.w) + 3] = 255 *l3;
		}
	}

	this.blue.updatePixels();
	this.dark.updatePixels();
	this.light.updatePixels();
}

/*--------------*/

Nebula.prototype.displayBG = function() {
	imageMode(CORNER);
	image(this.blue, 0, 0);
}

/*--------------*/

Nebula.prototype.displayFG = function() {
	imageMode(CORNER);
	image(this.dark, 0, 0);
	image(this.light, 0, 0);
}

