function Star(w, h) {
	this.img = createGraphics(w, h);
	this.img.noStroke();

	this.w = w;
	this.h = h;
}

/*--------------*/

Star.prototype.clear = function() {
	this.img.clear();
}

/*--------------*/

Star.prototype.addSimpleStar = function(qty, size, alpha) {
	this.img.fill(255, alpha);
  for (let i = 0; i < qty; i++)
    this.img.ellipse(random(this.w), random(this.h), size);
}

/*--------------*/

Star.prototype.addBigStar = function(qty) {
	this.img.rectMode(CENTER);

	for (let i = 0; i < qty; i++) {
		let x = random(this.w);
		let y = random(this.h);

		this.img.fill(255, 5);
		this.img.ellipse(x, y, 50);

		this.img.fill(255, 15);
		this.img.ellipse(x, y, 30);

		this.img.rect(x, y, 40, 3);
		this.img.rect(x, y, 3, 60);

		this.img.fill(255, 30);
		this.img.ellipse(x, y, 15);

		this.img.fill(255, 200);
		this.img.ellipse(x, y, 5);
	}
}

/*--------------*/

Star.prototype.display = function(x, y) {
	imageMode(CORNER);
	image(this.img, x, y);
}
